169	/**
170	 * The flat ODF leg: substitute in the XML, then convert.
171	 *
172	 * The filled flat file stays in the output directory as the diffable record of
173	 * what was filled. It is not the thing a fix edits: this function re-reads its
174	 * `--template` and rewrites the record on every run, so an edit there is
175	 * discarded with no error. The fix loop the skill documents edits a copy of the
176	 * template (`template <fmt> --out DIR`) and passes that copy as `--template`.
177	 */
178	function fillFlat({ template, data, out }) {
179	  const t0 = Date.now();
180	  // The flat file lands beside the output, and the caller's `--out` names a
181	  // directory that need not exist yet: the skill's own first example is
182	  // `--out out/report.docx` on a tree with no `out/`, and the UNO leg already
183	  // creates it (`fillUno`). Without this the write below throws ENOENT before any
184	  // conversion has happened, which reads as a broken script rather than a missing
185	  // directory.
186	  mkdirSync(dirname(resolve(out)), { recursive: true });
187	  let text = readFileSync(template, "utf8");
188	  const missing = [];
189	  for (const [key, value] of Object.entries(data)) {
190	    const placeholder = `{{${key}}}`;
191	    if (!text.includes(placeholder)) missing.push(key);
192	    // A function replacement, not a string one: in a string replacement, a
193	    // dollar sign followed by an ampersand or a quote in the replacement text
194	    // is a pattern — it can re-insert the placeholder or the rest of the
195	    // document — so a currency value written as USD with a thousands
196	    // apostrophe after the dollar sign would duplicate the document tail. The
197	    // function form inserts the escaped value literally.
198	    text = text.replaceAll(placeholder, () => xmlEscape(value));
199	  }
200	  const target = extensionOf(out);
201	  // Asked for the template's own format, the filled file *is* the output: naming it
202	  // a second way from `out` gave two names for one file, and the copy that followed
203	  // was a file onto itself — which leaves the bytes alone here and is not something
204	  // to rest on. One name, written once.
205	  const sameFormat = target === extensionOf(template);
206	  const flat = sameFormat
207	    ? resolve(out)
208	    : join(dirname(resolve(out)), `${basename(out, `.${target}`)}.${extensionOf(template)}`);
209	  writeFileSync(flat, text);
210	  const leftover = [...new Set(text.match(PLACEHOLDER) ?? [])];
211	
212	  if (sameFormat) {
213	    return {
214	      leg: "flat-odf",
215	      template,
216	      out: resolve(out),
217	      flatOdf: flat,
218	      converted: false,
219	      keysNotInTemplate: missing,
220	      leftInTemplate: leftover,
221	      unfilled: leftover,
222	      seconds: (Date.now() - t0) / 1000,
223	    };
224	  }
225	  const soffice = ensure({ lo: true }).soffice;
226	  if (!soffice) fail("fill: LibreOffice is not available, so the flat ODF file could not be converted");
227	  const converted = convert(soffice, { file: flat, to: target, outdir: dirname(resolve(out)) });
228	  if (!converted.ok) fail(`fill: conversion to ${target} failed: ${(converted.stderr ?? "").slice(0, 400)}`);
229	  if (converted.path !== resolve(out)) copyFileSync(converted.path, resolve(out));
230	  return {
231	    leg: "flat-odf",
232	    template,
233	    out: resolve(out),
234	    flatOdf: flat,
235	    converted: true,
236	    keysNotInTemplate: missing,
237	    leftInTemplate: leftover,
238	    unfilled: leftover,
239	    seconds: (Date.now() - t0) / 1000,
240	  };
241	}
